using System;
using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using Astrea.RunModifiers;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;
using UnityEngine.UI;

namespace Astrea;

public class ActionDescriptionPanel : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private ActionDescriptionInstance actionDescriptionInstance;

	[SerializeField]
	private ActionDescriptionInstance secondActionDescriptionInstance;

	[SerializeField]
	private ActionDescriptionInstancePositioner actionDescriptionInstancePositioner;

	[SerializeField]
	private ActionDescriptionInstance actionDescriptionInstanceExtraTags;

	[SerializeField]
	private ContentSizeFitterWithMaxMinSize contentSizeFitterWithMaxMinSize;

	[SerializeField]
	private DieFacesPanel dieFacesPanel;

	[Header("Effects")]
	[SerializeField]
	private GameObject tagDescriptionPrefab;

	[SerializeField]
	private Transform tagDescriptionHolder;

	[Header("Reference")]
	[SerializeField]
	private CameraReference mainCameraReference;

	[SerializeField]
	private CameraReference diceTossingCameraReference;

	[SerializeField]
	private CameraReference dicePreviewCameraReference;

	[SerializeField]
	private CanvasReference tooltipCanvas;

	public List<GameObject> tagDescriptionInstanceGOs = new List<GameObject>();

	private Coroutine fadeCoroutine;

	private RectTransform actionDescriptionInstanceRect;

	private RectTransform actionDescriptionInstanceExtraTagsRect;

	private Camera cameraToUseAsReferenceToPosition;

	private float actionDescriptionInstanceMaxHeight = 2260f;

	private float actionDescriptionInstanceMaxHeightDownAlignmentWithoutVerticalPadding = 2120f;

	private float actionDescriptionInstanceMaxHeightDownAlignmentWithoutVerticalPaddingSecondLine = 2050f;

	private float actionDescriptionInstanceExtraTagsXPosition = 692f;

	private float fontSizeDefault;

	private bool downAlignmentWithoutVerticalPadding;

	public ActionDescriptionInstancePositioner ActionDescriptionInstancePositioner => actionDescriptionInstancePositioner;

	public float ActionDescriptionInstanceExtraTagsXPosition => actionDescriptionInstanceExtraTagsXPosition;

	private void Awake()
	{
		actionDescriptionInstanceRect = actionDescriptionInstance.GetComponent<RectTransform>();
		actionDescriptionInstanceExtraTagsRect = actionDescriptionInstanceExtraTags.GetComponent<RectTransform>();
		fontSizeDefault = actionDescriptionInstance.ActionDescriptionText.fontSizeMax;
	}

	public void SetPosition(CameraEnum cameraEnum, Vector3 actionDescriptionPanelPosition)
	{
		base.transform.SetParent(tooltipCanvas.Value.transform);
		switch (cameraEnum)
		{
		case CameraEnum.MainCamera:
			cameraToUseAsReferenceToPosition = mainCameraReference.value;
			break;
		case CameraEnum.DiceTossing:
			cameraToUseAsReferenceToPosition = diceTossingCameraReference.value;
			break;
		case CameraEnum.DicePreview:
			cameraToUseAsReferenceToPosition = dicePreviewCameraReference.value;
			break;
		}
		base.transform.position = cameraToUseAsReferenceToPosition.WorldToScreenPoint(actionDescriptionPanelPosition.ZeroZ());
		base.transform.localScale = Vector3.one;
	}

	public void Initialize(ActionFace actionFace, string instanceTypeString = "", Dice dice = null, bool upAlignment = true, bool forgeDiceFace = false, bool isDiceInstance = false, DiceOwnerEnum diceOwnerEnum = DiceOwnerEnum.PLAYER)
	{
		SetAlignment(upAlignment);
		StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel();
		bool addTimelessTag = !actionFace.EnableSecondAction;
		bool addTimelessTag2 = true;
		if (actionFace is DiceFace && (actionFace as DiceFace).Timeless)
		{
			addTimelessTag = false;
			addTimelessTag2 = false;
		}
		actionDescriptionInstance.InitializeFirstAction(actionFace, instanceTypeString, addTimelessTag, dice, forgeDiceFace);
		BaseBattleActionData baseBattleActionData = actionFace.BattleAction.BaseBattleActionData;
		if (baseBattleActionData.ShowEffectsAndTagsBeforeActionFaceForDescriptions)
		{
			InitializeActionEffectsAndTags(baseBattleActionData, dice, addTimelessTag2, actionFace.BattleAction);
			InitializeSecondaryBattleActionDescription(baseBattleActionData.ActionFaceForDescriptions, actionFace.ActionValue);
		}
		else
		{
			InitializeSecondaryBattleActionDescription(baseBattleActionData.ActionFaceForDescriptions, actionFace.ActionValue);
			InitializeActionEffectsAndTags(baseBattleActionData, dice, addTimelessTag2, actionFace.BattleAction);
		}
		if (baseBattleActionData.AfterAllTagsTags != null)
		{
			for (int i = 0; i < baseBattleActionData.AfterAllTagsTags.Length; i++)
			{
				GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(tagDescriptionPrefab.name, tagDescriptionHolder);
				tagDescriptionInstanceGOs.Add(@object);
				@object.GetComponent<ActionDescriptionInstance>().UpdateTagDescriptionText(baseBattleActionData.AfterAllTagsTags[i]);
			}
		}
		if (actionFace.EnableSecondAction)
		{
			secondActionDescriptionInstance.gameObject.SetActive(value: true);
			secondActionDescriptionInstance.InitializeSecondAction(actionFace, dice);
			InitializeActionEffectsAndTags(actionFace.SecondBattleAction.BaseBattleActionData, dice);
			InitializeSecondaryBattleActionDescription(actionFace.SecondBattleAction.BaseBattleActionData.ActionFaceForDescriptions, actionFace.SecondActionValue);
		}
		else
		{
			secondActionDescriptionInstance.gameObject.SetActive(value: false);
		}
		if (actionFace is DiceFace && (actionFace as DiceFace).Timeless)
		{
			string text = "\n\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDotAtTheEndFormat(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("Timeless_N"));
			text = "<b><color=#FFC600>" + text + "</color></b>";
			if (!actionFace.EnableSecondAction)
			{
				actionDescriptionInstance.ActionDescriptionText.text += text;
			}
			else
			{
				secondActionDescriptionInstance.ActionDescriptionText.text += text;
			}
			GameObject object2 = ReferenceSingleton<PoolHandler>.Instance.GetObject(tagDescriptionPrefab.name, tagDescriptionHolder);
			tagDescriptionInstanceGOs.Add(object2);
			object2.GetComponent<ActionDescriptionInstance>().UpdateTagDescriptionText(ReferenceSingleton<AssetsReference>.Instance.TimelessTag);
		}
		if (isDiceInstance)
		{
			dieFacesPanel.gameObject.SetActive(value: true);
			dieFacesPanel.InitializeDieFaces(dice);
			if (upAlignment)
			{
				dieFacesPanel.GetComponent<RectTransform>().pivot = new Vector2(0.5f, 0f);
			}
			else
			{
				dieFacesPanel.GetComponent<RectTransform>().pivot = new Vector2(0.5f, 1f);
			}
			if (diceOwnerEnum == DiceOwnerEnum.COMPANION)
			{
				dieFacesPanel.GetComponent<RectTransform>().SetAnchoredPositionX(640f);
			}
			else
			{
				dieFacesPanel.GetComponent<RectTransform>().SetAnchoredPositionX(-640f);
			}
		}
		CheckActionDescriptionSizeMakeAdjustments(upAlignment);
	}

	private void SetAlignment(bool upAlignment, bool centerAlignment = false, bool downAlignmentWithoutVerticalPadding = false)
	{
		this.downAlignmentWithoutVerticalPadding = downAlignmentWithoutVerticalPadding;
		actionDescriptionInstancePositioner.SetAlignment(upAlignment, centerAlignment);
	}

	private void StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel()
	{
		for (int i = 0; i < tagDescriptionInstanceGOs.Count; i++)
		{
			ReferenceSingleton<PoolHandler>.Instance.StoreObject(tagDescriptionInstanceGOs[i]);
		}
		tagDescriptionInstanceGOs.Clear();
		dieFacesPanel.gameObject.SetActive(value: false);
	}

	public void InitializeOnlyNameActionDescriptionPanel(NodeViewData nodeViewData)
	{
		SetAlignment(upAlignment: true);
		StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel();
		secondActionDescriptionInstance.gameObject.SetActive(value: false);
		actionDescriptionInstance.InitializeOnlyNameActionDescriptionPanel(nodeViewData);
		actionDescriptionInstanceExtraTags.gameObject.SetActive(value: false);
	}

	public void DisableActionDescriptionPanelDescription()
	{
		actionDescriptionInstance.DisableActionDescriptionPanelDescription();
	}

	public void InitializeOmenInstance(OmenData omenData, bool upAlignment, bool downAlignmentWithoutVerticalPadding, OmenInstance omenInstance = null)
	{
		SetAlignment(upAlignment, centerAlignment: false, downAlignmentWithoutVerticalPadding);
		InitializeOmenData(omenData, upAlignment, omenInstance);
	}

	public void InitializeOmenRewardInstance(OmenData omenData)
	{
		SetAlignment(upAlignment: true);
		InitializeOmenData(omenData, upAlignment: true);
	}

	private void InitializeOmenData(OmenData omenData, bool upAlignment, OmenInstance omenInstance = null)
	{
		StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel();
		actionDescriptionInstance.InitializeOmenDescription(omenData, omenInstance);
		if (omenData.EnableBattleAction)
		{
			if (omenData.EnableBattleActionAsTag)
			{
				InitializeSecondaryBattleActionDescription(omenData.BattleAction, omenData.ActionValue);
				InitializeSecondaryBattleActionDescription(omenData.BattleAction.BaseBattleActionData.ActionFaceForDescriptions, omenData.ActionValue);
			}
			if (!omenData.ShowBattleActionTagsEffectsAfterOmenDataTagsEffects)
			{
				InitializeActionEffectsAndTags(omenData.BattleAction.BaseBattleActionData);
			}
		}
		InitializeSecondaryEffectsAndTagsDescriptions(omenData.Effects, omenData.Tags, omenData.ShowTagsBeforeEffectsForDescriptions);
		if (omenData is GainSomethingWithDrawBackOmenData)
		{
			GainSomethingWithDrawBackOmenData gainSomethingWithDrawBackOmenData = omenData as GainSomethingWithDrawBackOmenData;
			InitializeActionEffectsAndTags(gainSomethingWithDrawBackOmenData.GoodEffectAction.BaseBattleActionData);
			InitializeActionEffectsAndTags(gainSomethingWithDrawBackOmenData.BadEffectAction.BaseBattleActionData);
		}
		InitializeSecondaryBattleActionDescription(omenData.ActionFaceForDescriptions, omenData.ActionValue);
		if (omenData is AquarianOrbsOmenData)
		{
			AquarianOrbsOmenData aquarianOrbsOmenData = omenData as AquarianOrbsOmenData;
			InitializeAquarianOrbsOmenDataTagsDescriptions(actionDescriptionInstance, aquarianOrbsOmenData.StarAbilities);
		}
		if (omenData.ShowBattleActionTagsEffectsAfterOmenDataTagsEffects)
		{
			InitializeActionEffectsAndTags(omenData.BattleAction.BaseBattleActionData);
		}
		secondActionDescriptionInstance.gameObject.SetActive(value: false);
		CheckActionDescriptionSizeMakeAdjustments(upAlignment, omenInstance);
	}

	private void InitializeAquarianOrbsOmenDataTagsDescriptions(ActionDescriptionInstance actionDescriptionInstance, StarAbility[] starAbilities)
	{
		for (int i = 0; i < starAbilities.Length; i++)
		{
			GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(tagDescriptionPrefab.name, tagDescriptionHolder);
			@object.GetComponent<ActionDescriptionInstance>().UpdateStarAbilityDescriptionText(starAbilities[i]);
			tagDescriptionInstanceGOs.Add(@object);
			for (int j = 0; j < starAbilities[i].Effects.Length; j++)
			{
				GameObject object2 = ReferenceSingleton<PoolHandler>.Instance.GetObject(tagDescriptionPrefab.name, tagDescriptionHolder);
				object2.GetComponent<ActionDescriptionInstance>().UpdateEffectDescriptionText(starAbilities[i].Effects[j]);
				tagDescriptionInstanceGOs.Add(object2);
			}
		}
	}

	public void Initialize(EffectInstance effectInstance, GameObject effectOwner, bool upAlignment = true)
	{
		SetAlignment(upAlignment);
		StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel();
		actionDescriptionInstance.UpdateEffectDescriptionText(effectInstance, effectOwner);
		InitializeEffectsExtraEffectsAndTags(effectInstance.Effect, effectInstance.EffectAmount);
		secondActionDescriptionInstance.gameObject.SetActive(value: false);
		CheckActionDescriptionSizeMakeAdjustments(upAlignment);
	}

	public void Initialize(OverCorruptionAction overCorruptionAction)
	{
		SetAlignment(upAlignment: true);
		StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel();
		actionDescriptionInstance.InitializeOverCorruptedAction(overCorruptionAction);
		InitializeActionEffectsAndTags(overCorruptionAction.BattleAction.BaseBattleActionData);
		secondActionDescriptionInstance.gameObject.SetActive(value: false);
		CheckActionDescriptionSizeMakeAdjustments(upAlignment: true);
	}

	public void InitializeButtonDescription(ButtonDescriptionData buttonDescriptionData, int firstValue = -1)
	{
		SetAlignment(buttonDescriptionData.TooltipUpAlignment, buttonDescriptionData.TooltipCenterAlignment);
		StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel();
		secondActionDescriptionInstance.gameObject.SetActive(value: false);
		actionDescriptionInstance.InitializeButtonDescription(buttonDescriptionData, firstValue);
		InitializeSecondaryEffectsAndTagsDescriptions(buttonDescriptionData.GetEffects(), buttonDescriptionData.Tags, buttonDescriptionData.ShowTagsBeforeEffectsForDescriptions);
		actionDescriptionInstance.ActionDescriptionText.enableAutoSizing = true;
		CheckActionDescriptionSizeMakeAdjustments(buttonDescriptionData.TooltipUpAlignment);
	}

	public void InitializeStarAbility(StarAbility starAbility)
	{
		SetAlignment(upAlignment: false);
		StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel();
		secondActionDescriptionInstance.gameObject.SetActive(value: false);
		actionDescriptionInstance.InitializeStarAbility(starAbility);
		InitializeSecondaryEffectsAndTagsDescriptions(starAbility.Effects, starAbility.Tags, showTagsBeforeEffectsForDescriptions: false);
		CheckActionDescriptionSizeMakeAdjustments(upAlignment: false);
	}

	public void InitializeRunModifier(RunModifier runModifier)
	{
		SetAlignment(upAlignment: true);
		StoreAllPreviouslyEffectsPrefabsAndDisableDieFacesPanel();
		secondActionDescriptionInstance.gameObject.SetActive(value: false);
		actionDescriptionInstance.InitializeRunModifier(runModifier);
		InitializeSecondaryEffectsAndTagsDescriptions(runModifier.Effects, runModifier.Tags, showTagsBeforeEffectsForDescriptions: false);
		InitializeSecondaryBattleActionDescription(runModifier.ActionFaceForDescriptions, -2);
		actionDescriptionInstance.ActionDescriptionText.enableAutoSizing = true;
		CheckActionDescriptionSizeMakeAdjustments(upAlignment: true);
	}

	private void InitializeActionEffectsAndTags(BaseBattleActionData baseBattleActionData, Dice dice = null, bool addTimelessTag = false, BattleAction battleActionDiceAction = null)
	{
		InitializeSecondaryEffectsAndTagsDescriptions(baseBattleActionData.Effects, baseBattleActionData.GetTags(addTimelessTag, dice, battleActionDiceAction), baseBattleActionData.ShowTagsBeforeEffectsForDescriptions);
	}

	private void InitializeEffectsExtraEffectsAndTags(Effect effect, int amount)
	{
		InitializeSecondaryEffectsAndTagsDescriptions(effect.ExtraEffects, effect.Tags, showTagsBeforeEffectsForDescriptions: false);
		InitializeSecondaryBattleActionDescription(effect.ActionFaceForDescriptions, amount);
	}

	private void InitializeSecondaryEffectsAndTagsDescriptions(Effect[] effects, Tag[] tags, bool showTagsBeforeEffectsForDescriptions)
	{
		Action action = delegate
		{
			if (effects != null)
			{
				for (int j = 0; j < effects.Length; j++)
				{
					GameObject object2 = ReferenceSingleton<PoolHandler>.Instance.GetObject(tagDescriptionPrefab.name, tagDescriptionHolder);
					object2.GetComponent<ActionDescriptionInstance>().UpdateEffectDescriptionText(effects[j]);
					tagDescriptionInstanceGOs.Add(object2);
				}
			}
		};
		Action action2 = delegate
		{
			if (tags != null)
			{
				for (int i = 0; i < tags.Length; i++)
				{
					GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(tagDescriptionPrefab.name, tagDescriptionHolder);
					tagDescriptionInstanceGOs.Add(@object);
					@object.GetComponent<ActionDescriptionInstance>().UpdateTagDescriptionText(tags[i]);
				}
			}
		};
		if (showTagsBeforeEffectsForDescriptions)
		{
			action2();
			action();
		}
		else
		{
			action();
			action2();
		}
	}

	private void InitializeSecondaryBattleActionDescription(ActionFaceForDescription[] actionFaceForDescriptions, int amount)
	{
		foreach (ActionFaceForDescription actionFaceForDescription in actionFaceForDescriptions)
		{
			int amount2 = (actionFaceForDescription.EnableFixedActionValue ? actionFaceForDescription.ActionValue : amount);
			InitializeSecondaryBattleActionDescription(actionFaceForDescription.BattleAction, amount2);
		}
	}

	private void InitializeSecondaryBattleActionDescription(BattleAction battleAction, int amount)
	{
		GameObject @object = ReferenceSingleton<PoolHandler>.Instance.GetObject(tagDescriptionPrefab.name, tagDescriptionHolder);
		@object.GetComponent<ActionDescriptionInstance>().UpdateBattleActionDescriptionAsTag(battleAction, amount);
		tagDescriptionInstanceGOs.Add(@object);
	}

	[Button(null)]
	public void SetAlphaToZero()
	{
		actionDescriptionInstance.SetAlphaToZero();
	}

	[Button(null)]
	public void SetAlphaToOne()
	{
		actionDescriptionInstance.SetAlphaToOne();
	}

	public void Fade(bool fadeIn, Action afterFadeAction, float tooltipDelay)
	{
		if (!fadeIn)
		{
			if (fadeCoroutine != null)
			{
				StopCoroutine(fadeCoroutine);
			}
			fadeCoroutine = StartCoroutine(FadeCoroutine(fadeIn, afterFadeAction, tooltipDelay));
		}
		else
		{
			StartCoroutine(FadeCoroutine(fadeIn, afterFadeAction, tooltipDelay));
		}
	}

	public IEnumerator FadeCoroutine(bool fadeIn, Action afterFadeAction, float tooltipDelay)
	{
		if (fadeIn)
		{
			actionDescriptionInstancePositioner.AdjustAnchor(downAlignmentWithoutVerticalPadding);
		}
		actionDescriptionInstance.Fade(fadeIn);
		yield return new WaitForSecondsRealtime(tooltipDelay - 0.05f);
		afterFadeAction?.Invoke();
	}

	public void OverridePositions(TransformPositionOverride[] transformPositionOverrides)
	{
		PositionOverride[] array = new PositionOverride[transformPositionOverrides.Length];
		for (int i = 0; i < transformPositionOverrides.Length; i++)
		{
			Vector3 positionOverridePosition = cameraToUseAsReferenceToPosition.WorldToScreenPoint(transformPositionOverrides[i].positionOverrideTransform.position.ZeroZ());
			array[i] = new PositionOverride(transformPositionOverrides[i].positionOverrideType, positionOverridePosition);
		}
		actionDescriptionInstancePositioner.OverridePositions(array);
	}

	private void CheckActionDescriptionSizeMakeAdjustments(bool upAlignment, OmenInstance omenInstance = null)
	{
		actionDescriptionInstance.ActionDescriptionText.enableAutoSizing = false;
		actionDescriptionInstance.ActionDescriptionText.fontSize = fontSizeDefault;
		contentSizeFitterWithMaxMinSize.maxHeight = -1f;
		LayoutRebuilder.ForceRebuildLayoutImmediate(actionDescriptionInstanceRect);
		float num = actionDescriptionInstanceMaxHeight;
		if (downAlignmentWithoutVerticalPadding)
		{
			num = ((!(omenInstance != null)) ? actionDescriptionInstanceMaxHeightDownAlignmentWithoutVerticalPadding : ((!(omenInstance.transform.position.y >= 4.045f)) ? actionDescriptionInstanceMaxHeightDownAlignmentWithoutVerticalPaddingSecondLine : actionDescriptionInstanceMaxHeightDownAlignmentWithoutVerticalPadding));
		}
		if (actionDescriptionInstanceRect.sizeDelta.y > num)
		{
			actionDescriptionInstanceExtraTags.gameObject.SetActive(value: true);
			for (int num2 = tagDescriptionInstanceGOs.Count - 1; num2 >= 0; num2--)
			{
				if (actionDescriptionInstanceRect.sizeDelta.y > num)
				{
					tagDescriptionInstanceGOs[num2].transform.SetParent(actionDescriptionInstanceExtraTags.transform);
					tagDescriptionInstanceGOs[num2].transform.SetAsFirstSibling();
					LayoutRebuilder.ForceRebuildLayoutImmediate(actionDescriptionInstanceRect);
				}
			}
			contentSizeFitterWithMaxMinSize.maxHeight = num;
			actionDescriptionInstance.ActionDescriptionText.enableAutoSizing = true;
			LayoutRebuilder.ForceRebuildLayoutImmediate(actionDescriptionInstance.ActionDescriptionText.rectTransform);
			InvokeAlternatives.InvokeAfterMultipleFrames(this, 2, delegate
			{
				if (upAlignment)
				{
					upAlignment = actionDescriptionInstanceRect.pivot == new Vector2(0.5f, 0f);
					bool flag = actionDescriptionInstanceRect.pivot == new Vector2(0.5f, 0.5f);
					if (upAlignment)
					{
						actionDescriptionInstanceExtraTagsRect.SetAnchoredPositionY(actionDescriptionInstanceRect.anchoredPosition.y + actionDescriptionInstanceRect.rect.height);
					}
					else if (flag)
					{
						actionDescriptionInstanceExtraTagsRect.SetAnchoredPositionY(actionDescriptionInstanceRect.anchoredPosition.y + actionDescriptionInstanceRect.rect.height / 2f);
					}
					else
					{
						actionDescriptionInstanceExtraTagsRect.SetAnchoredPositionY(actionDescriptionInstanceRect.anchoredPosition.y);
					}
				}
			});
		}
		else
		{
			actionDescriptionInstanceExtraTags.gameObject.SetActive(value: false);
		}
	}

	public void SetActionDescriptionInstanceExtraTagsLeftOrRightPosition(bool right)
	{
		if (actionDescriptionInstanceExtraTags.gameObject.activeInHierarchy)
		{
			actionDescriptionInstanceExtraTagsRect.SetAnchoredPositionX(actionDescriptionInstanceRect.anchoredPosition.x + actionDescriptionInstanceExtraTagsXPosition * (float)(right ? 1 : (-1)));
		}
	}
}
